function SearchPage({navigate}){const [q,setQ]=useState('');const items=[['Practice Trading','Practice with market positions.'],['AI Trading','Manage AI-assisted practice.'],['Community Challenges','Compete in community challenges.'],['Referrals','Invite friends and track milestones.'],['Missions & Rewards','Earn Trade Credits through missions.'],['PXY Token','Explore PXY token allocations.'],['Activity','Review your recent activity.']];const matches=items.filter(i=>(i[0]+' '+i[1]).toLowerCase().includes(q.toLowerCase()));return <><Heading eyebrow="QUICK FIND" title="Where do you want to go?" desc="Find a destination or action."/><div className="search-page-input"><Search size={19}/><input placeholder="Search trading, challenges, rewards..." value={q} onChange={e=>setQ(e.target.value)}/><span>{matches.length} results</span></div><div className="search-results">{matches.map(i=><button key={i[0]} onClick={()=>navigate(i[0])}><span className="search-result-icon"><ArrowUpRight size={17}/></span><span><strong>{i[0]}</strong><small>{i[1]}</small></span><ChevronRight size={16}/></button>)}{matches.length===0&&<div className="empty-state"><h3>No matches</h3><p>Try a different search term.</p></div>}</div></>}
class PageErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { failed: false };
  }
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error, info) {
    console.error("Pexoriy page render failed:", this.props.screenName, error, info?.componentStack || "");
  }
  render() {
    if (this.state.failed) return <section className="panel page-render-error" role="alert">
      <ShieldCheck size={22}/>
      <h2>This screen could not load</h2>
      <p>{this.props.screenName || "This page"} hit an unexpected display error. Your account data has not been changed by this screen error.</p>
      <button className="btn btn-outline" onClick={() => this.setState({ failed: false })}>Try loading again</button>
    </section>;
    return this.props.children;
  }
}

